/* PLAN 061 1.3 (Blåkopian). Läses HÄR, efter att --band-h/--sheet-h
   satt arkets slutliga mått: linjernas x = arkets egna stationer
   (samma tal som #p-open/måttkedjan, 195,6/469,3 av 880), en gång
   per mätning som --band-h/--life, aldrig per bildruta. */
var chapterEl = process.querySelector('.process-chapter');
var sheetEl = process.querySelector('.process-sheet');
var titleEl = document.getElementById('process-title');
if (chapterEl && sheetEl && titleEl){
  var C = chapterEl.getBoundingClientRect();
  var L = sheetEl.getBoundingClientRect();
  var T = titleEl.getBoundingClientRect();
  var x1 = L.left, x2 = L.left + L.width * 195.6 / 880,
      x3 = L.left + L.width * 469.3 / 880, x4 = L.left + L.width - 1;
  chapterEl.style.setProperty('--x1', (x1 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x2', (x2 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x3', (x3 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x4', (x4 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--dn', Math.max(0, T.top - C.top - 40).toFixed(1) + 'px');
  /* B3: den blå delen finns bara där det blå är tomt. stage.bottom -
     max(fotots underkant, alla .ts underkanter) = den fria ytan;
     0 om < 64px eller om linjen x krockar tickstrecken ±16px,
     annars min(fri - 32, 22svh). */
  var stageEl = document.querySelector('.thesis-stage');
  var photoEl = document.querySelector('.thesis-photo-box');
  var tsEls = document.querySelectorAll('.ts');
  var tickEls = document.querySelectorAll('.thesis-ticks i');
  if (stageEl){
    var stageR = stageEl.getBoundingClientRect();
    var lowest = photoEl ? photoEl.getBoundingClientRect().bottom : 0;
    for (var ti = 0; ti < tsEls.length; ti++){
      lowest = Math.max(lowest, tsEls[ti].getBoundingClientRect().bottom);
    }
    var fri = stageR.bottom - lowest;
    var tickRects = [];
    for (var ki = 0; ki < tickEls.length; ki++) tickRects.push(tickEls[ki].getBoundingClientRect());
    var xs = [x1, x2, x3, x4];
    for (var xi = 0; xi < 4; xi++){
      var hitsTick = tickRects.some(function(r){ return xs[xi] >= r.left - 16 && xs[xi] <= r.right + 16; });
      var up = (fri < 64 || hitsTick) ? 0 : Math.min(fri - 32, 0.22 * vh);
