file.content:
var chapterEl = process.querySelector('.process-chapter');
var sheetEl = process.querySelector('.process-sheet');
var titleEl = document.getElementById('process-title');
if (chapterEl && sheetEl && titleEl){
  var C = chapterEl.getBoundingClientRect();
  var L = sheetEl.getBoundingClientRect();
  var T = titleEl.getBoundingClientRect();
  var x1 = L.left, x2 = L.left + L.width * 195.6 / 880,
      x3 = L.left + L.width * 469.3 / 880, x4 = L.left + L.width - 1;
  chapterEl.style.setProperty('--x1', (x1 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x2', (x2 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x3', (x3 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--x4', (x4 - C.left).toFixed(1) + 'px');
  chapterEl.style.setProperty('--dn', Math.max(0, T.top - C.top - 40).toFixed(1) + 'px');
  /* PLAN 062 B1. .tes-plane spänner alltid EXAKT 0..innerWidth (viewport-
     bredd, left:50%+translateX(-50%)) och C.top-vh..C.top (en
     viewporthöjd, direkt ovanför kapitlets egen överkant) - inga
     koordinatbyten mot C.left/C.top behövs för planet, bara för de
     befintliga --x/--dn-talen (som ligger INUTI .process-chapter,
     position:relative). Insetten räknas som "hur många px måste
     klippas in från planets EGNA kant för att bara arkets rektangel
     ska synas". */
  chapterEl.style.setProperty('--pl-t', Math.max(0, L.top - C.top + vh).toFixed(1) + 'px');
  chapterEl.style.setProperty('--pl-r', Math.max(0, window.innerWidth - L.right).toFixed(1) + 'px');
  chapterEl.style.setProperty('--pl-b', Math.max(0, C.top - L.bottom).toFixed(1) + 'px');
  chapterEl.style.setProperty('--pl-l', Math.max(0, L.left).toFixed(1) + 'px');
  /* B3: den blå delen finns bara där det blå är tomt. stage.bottom -
     max(fotots underkant, alla .ts underkanter) = den fria ytan;
     0 om < 64px eller om linjen x krockar tickstrecken ±16px,
     annars min(fri - 32, 22svh). */

