input.new_string:
/* PLAN 062 B1. .tes-plane spänner alltid EXAKT 0..innerWidth (viewport-
   bredd, left:50%+translateX(-50%)) och C.top-vh..C.top (en
   viewporthöjd, direkt ovanför kapitlets egen överkant).
   .process-sheet ligger INTE i .process-chapter - den är en
   SYSKON-sektion (.process-grid), fysiskt långt nedanför sidan
   medan --tx fortfarande löper, så dess LIVE rect (L) ligger
   utanför planets viewport-fönster och ger absurt stora insets
   (upptäckt live denna runda: --pl-b landade på 0, planet nådde
   aldrig ens ner till L.bottom). Målrektangeln byggs i stället ur
   arkets EGNA, redan validerade mått (samma x1/x4 som linjerna,
   ±1px mot arket i process-03) och dess låsta aspect-ratio
   (880/495, .process-sheet-CSS), landad vid SAMMA linje som
   landningslinjen (--dn): 40px ovanför rubriken. Två lager, en
   gemensam landningspunkt. */
var sheetAspect = 495 / 880;
var pW = x4 - x1;
var pH = pW * sheetAspect;
var landingY = T.top - 40;
var pTop = landingY - pH;
chapterEl.style.setProperty('--pl-t', Math.max(0, pTop - (C.top - vh)).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-r', Math.max(0, window.innerWidth - x4).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-b', Math.max(0, C.top - landingY).toFixed(1) + 'px');
chapterEl.style.setProperty('--pl-l', Math.max(0, x1).toFixed(1) + 'px');

