.tes-plane{position:absolute;left:50%;width:100vw;transform:translateX(-50%);
  bottom:100%;height:100vh;pointer-events:none;
  background:color-mix(in oklab,var(--c-accent),var(--c-drafting) calc(var(--tx) * 100%));
  clip-path:inset(calc(var(--tx) * var(--pl-t,0px)) calc(var(--tx) * var(--pl-r,0px))
    calc(var(--tx) * var(--pl-b,0px)) calc(var(--tx) * var(--pl-l,0px)));}

input.new_string:
/* Planet spänner FRÅN en viewporthöjd ovanför kanten TILL landningslinjen
   (samma --dn som linjerna redan landar vid, chapter-relativt) - inte
   bara ovanför kanten. Arkets rektangel landar med sin UNDERKANT exakt
   vid landningslinjen (samma punkt linjerna redan möts vid), så
   bottenklippet är alltid 0: ingen fjärde variabel behövs. */
.tes-plane{position:absolute;left:50%;width:100vw;transform:translateX(-50%);
  top:calc(-100vh);height:calc(100vh + var(--dn,0px));pointer-events:none;
  background:color-mix(in oklab,var(--c-accent),var(--c-drafting) calc(var(--tx) * 100%));
  clip-path:inset(calc(var(--tx) * var(--pl-t,0px)) calc(var(--tx) * var(--pl-r,0px))
    0 calc(var(--tx) * var(--pl-l,0px)));}

