from playwright.sync_api import sync_playwright
from PIL import Image
import io

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def relative_luminance(rgb):
    def lin(c):
        c = c / 255
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4
    r, g, b = rgb
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)

def contrast(a, b):
    la, lb = relative_luminance(a), relative_luminance(b)
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    for w, h in [(1920, 930), (1440, 900), (390, 844)]:
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL + "?preview=tes-till-ritning-4")
        pg.wait_for_timeout(1200)
        r = pg.evaluate("""() => {
          const plane = document.querySelector('.tes-plane');
          const title = document.getElementById('process-title');
          const pr = plane.getBoundingClientRect();
          const tr = title.getBoundingClientRect();
          const cs = getComputedStyle(plane);
          return {
            planeBottom: pr.bottom, titleTop: tr.top,
            gap: tr.top - pr.bottom,
            planeWidth: pr.width, planeHeight: pr.height,
            clipPath: cs.clipPath,
          };
        }""")
        shot = pg.screenshot()
        img = Image.open(io.BytesIO(shot))
        px = img.load()
        # sample the plane's visible rect via clip-path calc done in JS already;
        # just sample fill color at center and contour edge color near bottom-left corner
        cx, cy = w // 2, int(r["planeBottom"]) - 40
        cy = max(0, min(h - 1, cy))
        fill = px[cx, cy][:3]
        # contour: sample a pixel exactly on the bottom edge line (2px inset white box-shadow)
        edge_y = max(0, min(h - 1, int(r["planeBottom"]) - 2))
        contour = px[cx, edge_y][:3]
        print(w, h, r, "fill=", fill, "contour_sample=", contour, "contrast(contour,fill)=", round(contrast(contour, fill), 2))
        pg.close()
    b.close()

