(sel) => {
  function visRect(el) {
    const r = el.getBoundingClientRect();
    const cs = getComputedStyle(el);
    if (r.width <= 0 || r.height <= 0) return null;
    if (parseFloat(cs.opacity) < 0.02) return null;
    const m = /^inset\\(([^)]+)\\)/.exec(cs.clipPath);
    let top = r.top, right = r.right, bottom = r.bottom, left = r.left;
    if (m) {
      const raw = m[1].trim().split(/\\s+/);
      function val(tok, base) { return tok.endsWith('%') ? parseFloat(tok)/100*base : parseFloat(tok); }
      let it, ir, ib, il;
      if (raw.length === 1) { it = ir = ib = il = val(raw[0], r.height); }
      else if (raw.length === 2) { it = ib = val(raw[0], r.height); ir = il = val(raw[1], r.width); }
      else if (raw.length === 3) { it = val(raw[0], r.height); ir = il = val(raw[1], r.width); ib = val(raw[2], r.height); }
      else { it = val(raw[0], r.height); ir = val(raw[1], r.width); ib = val(raw[2], r.height); il = val(raw[3], r.width); }
      top = r.top + it; bottom = r.bottom - ib; left = r.left + il; right = r.right - ir;
      if (left >= right || top >= bottom) return null;
    }
    return { top, right, bottom, left };
  }
  const seamEls = Array.from(document.querySelectorAll('.seam i, .tes-plane'));
  const headEls = Array.from(document.querySelectorAll(sel));
  const hits = [];
  for (const s of seamEls) {
    const sr = visRect(s);
    if (!sr) continue;
    for (const h of headEls) {
      const hr = visRect(h);
      if (!hr) continue;
      const ix = Math.min(sr.right, hr.right) - Math.max(sr.left, hr.left);
      const iy = Math.min(sr.bottom, hr.bottom) - Math.max(sr.top, hr.top);
      if (ix > 0 && iy > 0) {
        hits.push({ seam: s.className, heading: h.tagName + '.' + h.className, ix: Math.round(ix), iy: Math.round(iy) });
      }
    }
  }
  return hits;
}
