from playwright.sync_api import sync_playwright
import sys

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def check(w, h):
    with sync_playwright() as p:
        b = p.chromium.launch()
        pg = b.new_page(viewport={"width": w, "height": h})
        client = pg.context.new_cdp_session(pg)
        client.send("Performance.enable")
        longtasks = []
        pg.evaluate("""() => {
          window.__longtasks = [];
          new PerformanceObserver((list) => {
            for (const e of list.getEntries()) {
              window.__longtasks.push({start: e.startTime, dur: e.duration});
            }
          }).observe({entryTypes: ['longtask']});
        }""")
        pg.goto(URL)
        pg.wait_for_timeout(700)
        # scroll to Calyx entrance first (mount Calyx normally), then scroll
        # through the whole Calyx->Horai transition in 120px ticks (Astra's
        # own step size for longtask18.py), recording task timestamps vs
        # scrollY so we can bucket the Calyx 0.80 -> Horai step-1 window.
        caseEl = pg.evaluate("document.getElementById('case-calyx').getBoundingClientRect().top + window.scrollY")
        pg.evaluate("window.scrollTo(0, %f - 200)" % caseEl)
        pg.wait_for_timeout(500)
        events = []
        for i in range(160):
            pg.mouse.wheel(0, 120)
            pg.wait_for_timeout(40)
            cur = pg.evaluate("""() => {
              const el = document.getElementById('case-calyx');
              return parseFloat(getComputedStyle(el).getPropertyValue('--sc-ps')) || 0;
            }""")
            events.append((i, cur))
        tasks = pg.evaluate("window.__longtasks")
        pg.close()
        b.close()
    return tasks, events

if __name__ == "__main__":
    for w, h in [(1440, 900), (1920, 930), (390, 844)]:
        tasks, events = check(w, h)
        long_over_50 = [t for t in tasks if t["dur"] > 50]
        print(w, h, "total long tasks:", len(tasks), "over 50ms:", len(long_over_50))
        for t in long_over_50:
            print("  ", t)

