1	from playwright.sync_api import sync_playwright
2	import sys
3	
4	URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
5	HEADING_SEL = "h1, h2, h3, .ts, .statement, .close-mailto"
6	
7	CHECK_JS = """
8	(sel) => {
9	  function visRect(el) {
10	    const r = el.getBoundingClientRect();
11	    const cs = getComputedStyle(el);
12	    if (r.width <= 0 || r.height <= 0) return null;
13	    if (parseFloat(cs.opacity) < 0.02) return null;
14	    const m = /^inset\\(([^)]+)\\)/.exec(cs.clipPath);
15	    let top = r.top, right = r.right, bottom = r.bottom, left = r.left;
16	    if (m) {
17	      const raw = m[1].trim().split(/\\s+/);
18	      function val(tok, base) { return tok.endsWith('%') ? parseFloat(tok)/100*base : parseFloat(tok); }
19	      let it, ir, ib, il;
20	      if (raw.length === 1) { it = ir = ib = il = val(raw[0], r.height); }
21	      else if (raw.length === 2) { it = ib = val(raw[0], r.height); ir = il = val(raw[1], r.width); }
22	      else if (raw.length === 3) { it = val(raw[0], r.height); ir = il = val(raw[1], r.width); ib = val(raw[2], r.height); }
23	      else { it = val(raw[0], r.height); ir = val(raw[1], r.width); ib = val(raw[2], r.height); il = val(raw[3], r.width); }
24	      top = r.top + it; bottom = r.bottom - ib; left = r.left + il; right = r.right - ir;
25	      if (left >= right || top >= bottom) return null;
26	    }
27	    return { top, right, bottom, left };
28	  }
29	  const seamEls = Array.from(document.querySelectorAll('.seam i, .tes-plane'));
30	  const headEls = Array.from(document.querySelectorAll(sel));
31	  const hits = [];
32	  for (const s of seamEls) {
33	    const sr = visRect(s);
34	    if (!sr) continue;
35	    for (const h of headEls) {
36	      const hr = visRect(h);
37	      if (!hr) continue;
38	      const ix = Math.min(sr.right, hr.right) - Math.max(sr.left, hr.left);
39	      const iy = Math.min(sr.bottom, hr.bottom) - Math.max(sr.top, hr.top);
40	      if (ix > 0 && iy > 0) {
41	        hits.push({ seam: s.className, heading: h.tagName + '.' + h.className, ix: Math.round(ix), iy: Math.round(iy) });
42	      }
43	    }
44	  }
45	  return hits;
46	}
47	"""
48	
49	def sweep(pg, width, height, step=20, inject=None):
50	    pg.set_viewport_size({"width": width, "height": height})
51	    pg.goto(URL)
52	    if inject:
53	        pg.add_style_tag(content=inject)
54	    pg.wait_for_timeout(600)
55	    total_h = pg.evaluate("document.documentElement.scrollHeight")
56	    all_hits = []
57	    y = 0
58	    frame = 0
59	    while y <= total_h:
60	        pg.evaluate("window.scrollTo(0, " + str(y) + ")")
61	        pg.wait_for_timeout(20)
62	        hits = pg.evaluate(CHECK_JS, HEADING_SEL)
63	        for h in hits:
64	            h["scrollY"] = y
65	        all_hits.extend(hits)
66	        y += step
67	        frame += 1
68	    return all_hits, frame
69	
70	if __name__ == "__main__":
71	    mode = sys.argv[1] if len(sys.argv) > 1 else "real"
72	    inject = None
73	    if mode == "broken-lines":
74	        inject = ".seam-dn{height:150vh !important;}"
75	    elif mode == "broken-plane":
76	        inject = ".tes-plane{clip-path:none !important;}"
77	    widths = [(1920,930),(1440,900),(768,1024),(390,844)]
78	    with sync_playwright() as p:
79	        b = p.chromium.launch()
