from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL + "?preview=tes-till-ritning-4")
    pg.wait_for_timeout(1200)
    r = pg.evaluate("""() => {
      const plane = document.querySelector('.tes-plane');
      const cs = getComputedStyle(plane);
      const ch = document.querySelector('.process-chapter');
      const chCs = getComputedStyle(ch);
      const sheet = document.querySelector('.process-sheet');
      const sr = sheet.getBoundingClientRect();
      const pr = plane.getBoundingClientRect();
      return {
        pT: chCs.getPropertyValue('--pl-t'), pR: chCs.getPropertyValue('--pl-r'),
        pB: chCs.getPropertyValue('--pl-b'), pL: chCs.getPropertyValue('--pl-l'),
        tx: chCs.getPropertyValue('--tx'),
        clipPath: cs.clipPath, bg: cs.backgroundColor,
        planeRect: {top: pr.top, left: pr.left, width: pr.width, height: pr.height},
        sheetRect: {top: sr.top, left: sr.left, right: sr.right, bottom: sr.bottom},
      };
    }""")
    import json
    print(json.dumps(r, indent=2))
    pg.close()
    b.close()

